function orderJobs(jobs) {
  if (!Array.isArray(jobs) || jobs.length === 0) return [];

  const idSet = new Set();
  const indegree = new Map();
  const graph = new Map();

  for (const job of jobs) {
    if (!job || typeof job.id !== 'string') return null;
    if (idSet.has(job.id)) return null;
    idSet.add(job.id);
    indegree.set(job.id, 0);
    graph.set(job.id, []);
  }

  for (const job of jobs) {
    const deps = Array.isArray(job.deps) ? job.deps : [];
    for (const dep of deps) {
      if (!idSet.has(dep)) return null;
      if (dep === job.id) return null;
      graph.get(dep).push(job.id);
      indegree.set(job.id, indegree.get(job.id) + 1);
    }
  }

  const ready = [...idSet].filter(id => indegree.get(id) === 0).sort();
  const result = [];

  while (ready.length > 0) {
    const id = ready.shift();
    result.push(id);
    for (const next of graph.get(id)) {
      indegree.set(next, indegree.get(next) - 1);
      if (indegree.get(next) === 0) {
        ready.push(next);
        ready.sort();
      }
    }
  }

  return result.length === jobs.length ? result : null;
}

function roundHalfEven(x, digits) {
  const f = Math.pow(10, digits);
  const y = x * f;
  const floor = Math.floor(y);
  const frac = y - floor;
  let r;
  if (frac > 0.5) {
    r = floor + 1;
  } else if (frac < 0.5) {
    r = floor;
  } else {
    r = (floor % 2 === 0) ? floor : floor + 1;
  }
  const result = r / f;
  return result === 0 ? 0 : result;
}

function orderJobs(jobs) {
  if (!Array.isArray(jobs)) return null;
  if (jobs.length === 0) return [];
  const indeg = new Map();
  const adj = new Map();
  for (const job of jobs) {
    if (indeg.has(job.id)) return null;
    indeg.set(job.id, 0);
    adj.set(job.id, []);
  }
  for (const job of jobs) {
    for (const dep of job.deps || []) {
      if (!indeg.has(dep)) return null;
      adj.get(dep).push(job.id);
      indeg.set(job.id, indeg.get(job.id) + 1);
    }
  }
  const ready = [...indeg.keys()].filter((id) => indeg.get(id) === 0).sort();
  const order = [];
  while (ready.length > 0) {
    const id = ready.shift();
    order.push(id);
    for (const next of adj.get(id)) {
      const d = indeg.get(next) - 1;
      indeg.set(next, d);
      if (d === 0) {
        let i = 0;
        while (i < ready.length && ready[i] < next) i++;
        ready.splice(i, 0, next);
      }
    }
  }
  return order.length === indeg.size ? order : null;
}
